using Contoso.Services;

namespace Contoso.Services.Tests;

public interface IGreeter { }
public sealed class Greeter : IGreeter { }

[TestClass]
public sealed class ServiceRegistryTests
{
    [TestMethod]
    public void Resolve_AfterRegister_ReturnsSameInstance()
    {
        var registry = new ServiceRegistry();
        var service = new Greeter();

        registry.Register<IGreeter>(service);
        var resolved = registry.Resolve<IGreeter>();

        Assert.AreSame(service, resolved);
    }

    [TestMethod]
    public void Resolve_Unregistered_ReturnsNull()
    {
        var registry = new ServiceRegistry();

        var resolved = registry.Resolve<IGreeter>();

        Assert.IsNull(resolved);
    }

    [TestMethod]
    public void GetAll_ContainsRegisteredService()
    {
        var registry = new ServiceRegistry();
        var service = new Greeter();

        registry.Register<IGreeter>(service);

        Assert.Contains(service, registry.GetAll());
    }

    [TestMethod]
    public void GetAll_AfterRemove_DoesNotContainService()
    {
        var registry = new ServiceRegistry();
        var service = new Greeter();
        registry.Register<IGreeter>(service);

        registry.Remove<IGreeter>();

        Assert.DoesNotContain(service, registry.GetAll());
    }

    [TestMethod]
    public void GetAll_BeforeAnyRegistration_IsEmpty()
    {
        var registry = new ServiceRegistry();

        Assert.IsEmpty(registry.GetAll());
    }

    [TestMethod]
    public void GetAll_AfterRegistration_IsNotEmpty()
    {
        var registry = new ServiceRegistry();

        registry.Register<IGreeter>(new Greeter());

        Assert.IsNotEmpty(registry.GetAll());
    }
}

